#include <bits/stdc++.h>using namespace std;#define int long long#define double long double void solve() {    int n, q;    cin >> n >> q;    vector<int> v(n + 1);    for (int i = 1; i <= n; i++) {        cin >> v[i];    }    vector<int> prefix(n + 1);    prefix[0] = 0;    for (int i = 1; i <= n; i++) {        prefix[i] = prefix[i - 1] + v[i];    }    int total = prefix[n];    for (int i = 0; i < q; i++) {        int l, r, k;        cin >> l >> r >> k;        int temporary_sum =            total + (r - l + 1) * k - (prefix[r] - prefix[l - 1]);        if (temporary_sum % 2 != 0) {            cout << "YES" << "\n";        } else {            cout << "NO" << "\n";        }    }} int32_t main() {    ios::sync_with_stdio(false);    cin.tie(0);    cout.tie(0);    int t;    cin >> t;    for (int i = 0; i < t; i++) {        solve();    }}